  "agentUsageObservations.list": {
    parameters: {
      query?: {
        projectId?: string;
        cursor?: number;
        limit?: number;
      };
      header?: never;
      path: {
        runId: string;
      };
      cookie?: never;
    };
    requestBody?: never;
    responses: {
      /** @description Sanitized engine observations, never billing or certified totals */
      200: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          "application/json": {
            /** @enum {string} */
            format: "agent-usage-observation-page-v1";
            runId: string;
            projectId?: string;
            observationCount: number;
            /** @enum {string} */
            coverage: "partial-or-unknown";
            /** @enum {string} */
            billingStatus: "unknown";
            items: {
              /** @enum {string} */
              format: "agent-usage-observation-v1";
              runId: string;
              sessionId: string;
              projectId?: string;
              /** @enum {string} */
              engineKind: "pi" | "codex" | "langgraph";
              cursor: number;
              /** @enum {string} */
              measurementScope:
                | "response-increment"
                | "run-total"
                | "session-total"
                | "unspecified";
              /** @enum {string} */
              inputAccounting:
                "includes-cache" | "excludes-cache" | "unspecified";
              inputTokens:
                | {
                    /** @enum {string} */
                    status: "reported";
                    value: number;
                  }
                | {
                    /** @enum {string} */
                    status: "unreported";
                  }
                | {
                    /** @enum {string} */
                    status: "invalid";
                  };
              outputTokens:
                | {
                    /** @enum {string} */
                    status: "reported";
                    value: number;
                  }
                | {
                    /** @enum {string} */
                    status: "unreported";
                  }
                | {
                    /** @enum {string} */
                    status: "invalid";
                  };
              cachedTokens:
                | {
                    /** @enum {string} */
                    status: "reported";
                    value: number;
                  }
                | {
                    /** @enum {string} */
                    status: "unreported";
                  }
                | {
                    /** @enum {string} */
                    status: "invalid";
                  };
              costEstimate?: {
                /** @enum {string} */
                source: "engine-reported-estimate";
                amount:
                  | {
                      /** @enum {string} */
                      status: "reported";
                      value: number;
                    }
                  | {
                      /** @enum {string} */
                      status: "unreported";
                    }
                  | {
                      /** @enum {string} */
                      status: "invalid";
                    };
                currency:
                  | {
                      /** @enum {string} */
                      status: "reported";
                      value: string;
                    }
                  | {
                      /** @enum {string} */
                      status: "unreported";
                    }
                  | {
                      /** @enum {string} */
                      status: "invalid";
                    };
                /** @enum {string} */
                billingStatus: "unknown";
              };
              /** @enum {string} */
              source: "engine-reported";
              /** @enum {string} */
              runClassification: "unknown";
              /** @enum {string} */
              billingStatus: "unknown";
              /** Format: date-time */
              recordedAt: string;
            }[];
            nextCursor?: number;
          };
        };
      };
      /** @description Invalid run-scoped cursor */
      400: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          "application/problem+json": {
            /** Format: uri */
            type: string;
            title: string;
            status: number;
            detail?: string;
            instance?: string;
            code?: string;
            /** Format: uuid */
            traceId: string;
            errors?: {
              [key: string]: string[];
            };
          };
        };
      };
      /** @description Run absent from requested project or global scope */
      404: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          "application/problem+json": {
            /** Format: uri */
            type: string;
            title: string;
            status: number;
            detail?: string;
            instance?: string;
            code?: string;
            /** Format: uuid */
            traceId: string;
            errors?: {
              [key: string]: string[];
            };
          };
        };
      };
      /** @description Evaluation has not been explicitly revealed */
      409: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          "application/problem+json": {
            /** Format: uri */
            type: string;
            title: string;
            status: number;
            detail?: string;
            instance?: string;
            code?: string;
            /** Format: uuid */
            traceId: string;
            errors?: {
              [key: string]: string[];
            };
          };
        };
      };
      /** @description Stored observation cannot be verified */
      503: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          "application/problem+json": {
            /** Format: uri */
            type: string;
            title: string;
            status: number;
            detail?: string;
            instance?: string;
            code?: string;
            /** Format: uuid */
            traceId: string;
            errors?: {
              [key: string]: string[];
            };
          };
        };
      };
    };
  };
