                    /** @enum {string} */
                    code:
                      | "MEDIA_RECORD_CHANGED"
                      | "MEDIA_RECORD_MISSING"
                      | "MEDIA_OWNER_UNAVAILABLE"
                      | "ORIGINAL_ARCHIVE_CHANGED"
                      | "ORIGINAL_ARCHIVE_UNBOUND"
                      | "DECLARED_RIGHTS_RESTRICTED"
                      | "DECLARED_PROVIDER_UNAVAILABLE"
                      | "SOURCE_STALE"
